using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_CastAmount", menuName = "Data/Battle/Logics/Enemy Action/Cast Amount")]
public class EnemyActionLogic_CastAmount : EnemyActionLogic
{
	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		battleAction.CastAmount(actionAmount, source);
	}
}
